// Extract Research Signals & Pain Point data from Notion DB
const items = $input.all();
const insights = [];
const skipped = [];

for (const it of items) {
  const r = it.json || {};
  const title = String(r.property_signal_title || r.name || '').trim();
  const angle = String(r.property_content_angle || '').trim();
  const exact_lang = String(r.property_exact_language || '').trim();
  const bottleneck = String((r.property_bottleneck || {}).name || r.property_bottleneck || '').trim();

  if (!title) {
    skipped.push({ id: r.id, reason: 'missing Signal Title' });
    continue;
  }

  let grounding = {};
  try {
    grounding = r.property_insight_json ? JSON.parse(r.property_insight_json) : {};
  } catch (e) {
    // Fallback if Insight JSON isn't present
    grounding = {};
  }

  insights.push({
    id: r.id,
    insight_title: title,
    content_anchor: angle || title,
    bottleneck: bottleneck || 'Client Acquisition',
    exact_language: exact_lang || title,
    signal_type: (r.property_signal_type || [])[0] || 'pain',
    theme: (r.property_theme || [])[0] || 'operations',
    bridge: grounding.bridge || angle || 'Systems-first support for coaches',
    hook_options: grounding.hooks || [exact_lang || title],
    service_link: grounding.service || 'CRM & Automation Setup'
  });
}

return [{ json: { count: insights.length, insights, skipped } }];

let parsed;
try {
  parsed = JSON.parse($input.first().json.choices[0].message.content);
} catch (e) {
  throw new Error('Planner khong tra ve JSON hop le: ' + String($input.first().json.choices[0].message.content).slice(0, 300));
}
const plan = parsed.content_plan;
if (!Array.isArray(plan) || !plan.length) {
  throw new Error('Planner khong tra ve content_plan hop le.');
}

const LIMIT = 1900;
const deferred = [];
let clean = [...plan];
while (clean.length > 1 && JSON.stringify(clean).length > LIMIT) {
  deferred.push(clean.pop());
}
let raw_plan_json = JSON.stringify(clean);

let markdown = '## Đề xuất Kế hoạch Bài viết Tuần này (3 posts/tuần)\n\n';
clean.forEach((p, idx) => {
  markdown += `**Bài ${idx+1} [${p.bottleneck || 'Bottleneck'}]:** ${p.topic}\n`;
  markdown += `- Nền tảng: ${p.platform} | Định dạng: ${p.format}\n`;
  markdown += `- Hook ngôn ngữ thật: \"${p.exact_language_hook || p.topic}\"\n\n`;
});

const capRichText = (s) => { const t = String(s || ''); return t.length > 2000 ? t.slice(0, 1997) + '...' : t; };
const usedIds = [...new Set(clean.map(p => p.entry_id).filter(Boolean))];
return [{ json: { proposal_text: capRichText(markdown), raw_plan_json, signal_ids: usedIds, deferred_count: deferred.length } }];
